\set ON_ERROR_STOP on
BEGIN;
\copy fraud_sim.simulation_runs (simulation_run_id, run_name, dataset_version, random_seed, started_at, completed_at, run_status, configuration, created_by) FROM '../output/simulation_runs.csv' WITH (FORMAT csv, HEADER true, NULL '', ENCODING 'UTF8');
\copy fraud_sim.customers (customer_id, simulation_run_id, customer_type, full_name, gender, dob, id_number_hash, phone_hash, email_hash, province, address_cluster_id, phone_cluster_id, occupation_group, income_band, customer_segment, onboarding_channel, onboarding_date, kyc_level, base_risk_level, customer_status, is_synthetic_identity_seed, is_mule_candidate_seed, created_at) FROM '../output/customers.csv' WITH (FORMAT csv, HEADER true, NULL '', ENCODING 'UTF8');
\copy fraud_sim.accounts (account_id, simulation_run_id, customer_id, account_no_hash, account_type, account_currency, open_date, status, branch_code, account_opening_channel, home_province, daily_transfer_limit, single_txn_limit, average_balance, dormant_since, created_at) FROM '../output/accounts.csv' WITH (FORMAT csv, HEADER true, NULL '', ENCODING 'UTF8');
\copy fraud_sim.devices (device_id, simulation_run_id, device_fingerprint, device_type, os, first_seen_at, trust_status, is_emulator, is_rooted_or_jailbroken, device_risk_score, account_login_count, created_at) FROM '../output/devices.csv' WITH (FORMAT csv, HEADER true, NULL '', ENCODING 'UTF8');
\copy fraud_sim.login_sessions (session_id, simulation_run_id, account_id, customer_id, device_id, login_at, ip_address, province, country, latitude, longitude, geo_source, vpn_flag, proxy_flag, login_result, failure_reason, auth_method, is_new_device, is_new_location, session_risk_score, session_end_at) FROM '../output/login_sessions.csv' WITH (FORMAT csv, HEADER true, NULL '', ENCODING 'UTF8');
\copy fraud_sim.beneficiaries (beneficiary_id, simulation_run_id, account_id, beneficiary_account_hash, beneficiary_bank, beneficiary_name, added_at, added_channel, status, is_internal_bank, beneficiary_risk_level, mule_cluster_id) FROM '../output/beneficiaries.csv' WITH (FORMAT csv, HEADER true, NULL '', ENCODING 'UTF8');
\copy fraud_sim.account_change_events (change_event_id, simulation_run_id, account_id, customer_id, changed_at, change_type, channel, device_id, verification_method, change_result, old_value_hash, new_value_hash, is_sensitive_change) FROM '../output/account_change_events.csv' WITH (FORMAT csv, HEADER true, NULL '', ENCODING 'UTF8');
\copy fraud_sim.transactions (transaction_id, simulation_run_id, account_id, customer_id, session_id, device_id, beneficiary_id, transaction_at, amount, currency, direction, transaction_type, channel, counterparty_account_hash, counterparty_bank, counterparty_internal_account_id, merchant_id, merchant_category_code, ip_address, province, country, vpn_flag, proxy_flag, status, failure_reason, balance_before, balance_after, created_at) FROM '../output/transactions.csv' WITH (FORMAT csv, HEADER true, NULL '', ENCODING 'UTF8');
\copy fraud_sim.transaction_features (transaction_id, feature_version, computed_at, is_new_device, is_new_beneficiary, is_after_sensitive_change, txn_count_10m, txn_count_1h, txn_amount_sum_24h, amount_to_median_ratio, failed_auth_count_30m, time_since_beneficiary_added_minutes, time_since_sensitive_change_minutes, features) FROM '../output/transaction_features.csv' WITH (FORMAT csv, HEADER true, NULL '', ENCODING 'UTF8');
\copy fraud_sim.auth_events (auth_event_id, simulation_run_id, transaction_id, session_id, change_event_id, account_id, customer_id, auth_at, auth_method, auth_result, failed_attempt_count, auth_risk_score) FROM '../output/auth_events.csv' WITH (FORMAT csv, HEADER true, NULL '', ENCODING 'UTF8');
\copy fraud_sim.sales_points (sales_point_id, simulation_run_id, sales_point_name, sales_point_address, province, region, opened_at, monthly_application_baseline, status, created_at) FROM '../output/sales_points.csv' WITH (FORMAT csv, HEADER true, NULL '', ENCODING 'UTF8');
\copy fraud_sim.sales_agents (sales_agent_id, simulation_run_id, sales_point_id, sales_agent_name, join_date, role, monthly_application_baseline, status, created_at) FROM '../output/sales_agents.csv' WITH (FORMAT csv, HEADER true, NULL '', ENCODING 'UTF8');
\copy fraud_sim.loan_applications (application_id, simulation_run_id, customer_id, application_at, loan_amount, loan_term_months, loan_product, loan_purpose, application_channel, sales_point_id, sales_agent_id, application_status, credit_underwriting_result, decision_at, device_id, ip_address, is_vpn, is_proxy, is_emulator, created_at) FROM '../output/loan_applications.csv' WITH (FORMAT csv, HEADER true, NULL '', ENCODING 'UTF8');
\copy fraud_sim.applicant_declared_profiles (declared_profile_id, simulation_run_id, application_id, customer_id, declared_full_name, declared_id_number_hash, declared_dob, declared_phone_hash, declared_email_hash, declared_permanent_address, declared_current_address, declared_marital_status, declared_dependents, address_cluster_id, profile_similarity_cluster_id, address_quality_score, created_at) FROM '../output/applicant_declared_profiles.csv' WITH (FORMAT csv, HEADER true, NULL '', ENCODING 'UTF8');
\copy fraud_sim.employment_income_profiles (employment_id, simulation_run_id, application_id, occupation_group, employer_name, employer_phone_hash, employer_phone_cluster_id, employer_phone_verification_status, is_employer_phone_reused, employer_address, employment_start_date, months_at_employer, declared_monthly_income, income_document_type, employer_cluster_id, created_at) FROM '../output/employment_income_profiles.csv' WITH (FORMAT csv, HEADER true, NULL '', ENCODING 'UTF8');
\copy fraud_sim.reference_contacts (reference_id, simulation_run_id, application_id, reference_name, relationship, reference_phone_hash, phone_reuse_count, reference_quality_score, reference_order, verification_status, created_at) FROM '../output/reference_contacts.csv' WITH (FORMAT csv, HEADER true, NULL '', ENCODING 'UTF8');
\copy fraud_sim.application_documents (document_id, simulation_run_id, application_id, document_type, document_hash, submitted_at, ocr_quality_score, tamper_score, duplicate_document_hash_count, id_front_back_match_flag, id_expired_flag, face_match_score, liveness_result, document_result, created_at) FROM '../output/application_documents.csv' WITH (FORMAT csv, HEADER true, NULL '', ENCODING 'UTF8');
\copy fraud_sim.credit_bureau_snapshots (bureau_snapshot_id, simulation_run_id, application_id, bureau_score, active_loan_count, dpd_max_12m, recent_inquiry_count, thin_file_flag, bureau_match_result, snapshot_at, created_at) FROM '../output/credit_bureau_snapshots.csv' WITH (FORMAT csv, HEADER true, NULL '', ENCODING 'UTF8');
\copy fraud_sim.disbursement_accounts (disbursement_id, simulation_run_id, application_id, receiving_account_hash, receiving_account_name, receiving_bank, same_as_applicant, account_reuse_count, linked_account_id, disbursement_status, disbursed_at, disbursed_amount, created_at) FROM '../output/disbursement_accounts.csv' WITH (FORMAT csv, HEADER true, NULL '', ENCODING 'UTF8');
\copy fraud_sim.loan_repayment_outcomes (loan_outcome_id, simulation_run_id, application_id, disbursed_at, first_due_date, first_payment_status, first_payment_days_past_due, contact_status_after_disbursement, dpd_30_flag, dpd_60_flag, dpd_90_flag, installments_due, installments_paid_on_time, total_amount_due, total_amount_paid, outstanding_balance, early_default_flag, writeoff_amount, loan_performance_status, credit_performance_label, fraud_outcome_label, outcome_observed_at, created_at) FROM '../output/loan_repayment_outcomes.csv' WITH (FORMAT csv, HEADER true, NULL '', ENCODING 'UTF8');
\copy fraud_sim.rules (rule_id, rule_code, rule_name, owner_domain, scenario_code, rule_type, description, severity, base_score, decision_flag, status, created_by, created_at) FROM '../output/rules.csv' WITH (FORMAT csv, HEADER true, NULL '', ENCODING 'UTF8');
\copy fraud_sim.decision_outcomes (decision_outcome_id, simulation_run_id, message_type, entity_type, entity_id, transaction_id, application_id, decision_at, decision_flag, risk_score_100, reason_codes, alert_recommended, alert_type, triage_queue, processing_latency_ms, created_at) FROM '../output/decision_outcomes.csv' WITH (FORMAT csv, HEADER true, NULL '', ENCODING 'UTF8');
\copy fraud_sim.rule_hits (rule_hit_id, simulation_run_id, decision_outcome_id, rule_id, evaluated_at, hit_flag, score_contribution, evaluated_values, reason_code, execution_order) FROM '../output/rule_hits.csv' WITH (FORMAT csv, HEADER true, NULL '', ENCODING 'UTF8');
\copy fraud_sim.alerts (alert_id, simulation_run_id, scenario_code, primary_rule_id, decision_outcome_id, entity_type, entity_id, customer_id, account_id, transaction_id, application_id, triggered_at, final_risk_score_100, severity, alert_status, alert_reason, score_explanation, assigned_to, closed_at, updated_at) FROM '../output/alerts.csv' WITH (FORMAT csv, HEADER true, NULL '', ENCODING 'UTF8');
\copy fraud_sim.cases (case_id, simulation_run_id, case_type, primary_customer_id, primary_account_id, primary_application_id, primary_alert_id, created_at, assigned_team, case_priority, case_status, resolution_at, resolution_reason, analyst_id, loss_amount, prevented_loss_amount) FROM '../output/cases.csv' WITH (FORMAT csv, HEADER true, NULL '', ENCODING 'UTF8');
\copy fraud_sim.verification_results (verification_id, simulation_run_id, owner_domain, transaction_id, application_id, alert_id, case_id, verified_at, verification_label, review_outcome, loss_amount, prevented_loss_amount) FROM '../output/verification_results.csv' WITH (FORMAT csv, HEADER true, NULL '', ENCODING 'UTF8');
\copy fraud_sim.fraud_ground_truth (fraud_event_id, simulation_run_id, owner_domain, scenario_code, primary_customer_id, primary_account_id, primary_transaction_id, primary_application_id, start_at, end_at, fraud_label, fraud_outcome, injection_method, expected_rule_codes, expected_decision_flag, loss_amount) FROM '../output/fraud_ground_truth.csv' WITH (FORMAT csv, HEADER true, NULL '', ENCODING 'UTF8');
COMMIT;
ANALYZE fraud_sim.customers;
ANALYZE fraud_sim.transactions;
ANALYZE fraud_sim.loan_applications;